import os
import torch


class Config:
    # ==========================================
    # General Settings
    # ==========================================
    SEED = 42
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    NUM_WORKERS = 4

    # ==========================================
    # Data Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # CSV Files (Generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # DICOM Directories
    TRAIN_DICOM_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DICOM_DIR = os.path.join(INPUT_DIR, "test")

    # Output / Cache Paths
    # We use idea_31 as the specific working directory for this run
    WORKING_DIR = "./working/idea_31"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "avr_dan_best.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # Ensure directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)

    # ==========================================
    # Image Preprocessing
    # ==========================================
    IMG_SIZE = 224  # Native resolution for EfficientNet-B0
    SLAB_COUNT = 3  # Tri-Slab

    # Normalization constants (ImageNet defaults)
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # ==========================================
    # Model Architecture
    # ==========================================
    BACKBONE_NAME = "efficientnet_b0"
    BACKBONE_PRETRAINED = True
    FEATURE_DIM = 1280  # Native output dim of EffNet-B0 (no projection)

    # Tabular Features
    # Continuous: Age, Percent
    # Categorical: Sex (2), SmokingStatus (3)
    # Total Input Dim after One-Hot Encoding: 1 (Age) + 1 (Percent) + 2 (Sex) + 3 (Smoking) = 7
    TABULAR_INPUT_DIM = 7

    # The dimension to project tabular features to (matching visual features)
    HIDDEN_DIM = 1280

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 16  # Adjusted for 2x backbones + Attention on GPU
    EPOCHS = 50
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2

    # Scheduler
    T_MAX = EPOCHS  # For CosineAnnealingLR
    ETA_MIN = 1e-6

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 8

    # Metric / Loss
    # Max absolute error to penalize
    MAX_ERROR_THRESHOLD = 1000.0
    # Minimum confidence value
    MIN_CONFIDENCE = 70.0

    # ==========================================
    # Debugging
    # ==========================================
    # Set to a small integer (e.g., 50) to run on a subset of data for quick testing
    # Set to None for full run
    DEBUG_SAMPLE_SIZE = None
